    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    rows = []
    for r, row in enumerate(grid):
        nonzero = {v for v in row if v}
        if len(nonzero) == 1 and sum(v != 0 for v in row) >= 2:
            color = next(iter(nonzero))
            gaps = [c for c, v in enumerate(row) if v == 0 and c > 0 and c + 1 < w and row[c-1] == color and row[c+1] == color]
            if gaps:
                rows.append((r, color, gaps))

    # Match each horizontal bar's gap position to the vertical source marker
    # in that column. The bar colors extend upwards and downwards from their
    # own rows; when several bars share a lane, their ordered colors partition it.
    cols = sorted({c for _, _, cs in rows for c in cs})
    for c in cols:
        bars = [(r, color) for r, color, cs in rows if c in cs]
        bars.sort()
        # Extend the first bar color to the top, and each subsequent color
        # from the midpoint/previous bar boundary through its own row.
        for i, (r, color) in enumerate(bars):
            lo = 0 if i == 0 else bars[i-1][0] + 1
            hi = r
            for rr in range(lo, hi + 1):
                g[rr][c] = color
        # Continue the lowest bar's color down the lane.
        if bars:
            r, color = bars[-1]
            for rr in range(r + 1, h):
                if grid[rr][c] != 0:
                    break
                g[rr][c] = color
    return g
